const API_BASE = '/api'

async function fetchApi<T>(endpoint: string, options?: RequestInit): Promise<T> {
  const response = await fetch(`${API_BASE}${endpoint}`, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...options?.headers,
    },
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Unknown error' }))
    throw new Error(error.error || `HTTP ${response.status}`)
  }

  return response.json()
}

// Types
export interface User {
  id: number
  email: string
  name: string
  role: string
  created_at: string
}

export interface Post {
  id: number
  user_id: number
  title: string
  content: string
  created_at: string
  author_name?: string
}

export interface KVKey {
  name: string
  expiration?: number
  metadata?: Record<string, unknown>
}

export interface R2Object {
  key: string
  size: number
  uploaded: string
}

// D1 API
export const d1Api = {
  getUsers: () => fetchApi<User[]>('/users'),
  getUser: (id: number) => fetchApi<User>(`/users/${id}`),
  createUser: (data: { email: string; name: string; role?: string }) =>
    fetchApi<{ success: boolean; id: number }>('/users', {
      method: 'POST',
      body: JSON.stringify(data),
    }),
  deleteUser: (id: number) =>
    fetchApi<{ success: boolean }>(`/users/${id}`, { method: 'DELETE' }),
  getPosts: () => fetchApi<Post[]>('/posts'),
}

// KV API
export const kvApi = {
  listKeys: (prefix?: string) =>
    fetchApi<{ keys: KVKey[] }>(`/kv${prefix ? `?prefix=${prefix}` : ''}`),
  getValue: (key: string) =>
    fetchApi<{ key: string; value: string }>(`/kv/${encodeURIComponent(key)}`),
  setValue: (key: string, value: string, ttl?: number) =>
    fetchApi<{ success: boolean; key: string }>(`/kv/${encodeURIComponent(key)}`, {
      method: 'PUT',
      body: JSON.stringify({ value, ttl }),
    }),
  deleteKey: (key: string) =>
    fetchApi<{ success: boolean }>(`/kv/${encodeURIComponent(key)}`, {
      method: 'DELETE',
    }),
}

// R2 API
export const r2Api = {
  listFiles: (prefix?: string) =>
    fetchApi<{ objects: R2Object[] }>(`/files${prefix ? `?prefix=${prefix}` : ''}`),
  uploadFile: async (key: string, file: File) => {
    const response = await fetch(`${API_BASE}/files/${encodeURIComponent(key)}`, {
      method: 'PUT',
      headers: { 'Content-Type': file.type || 'application/octet-stream' },
      body: file,
    })
    if (!response.ok) throw new Error(`Upload failed: ${response.status}`)
    return response.json() as Promise<{ success: boolean; key: string }>
  },
  downloadFile: (key: string) => `${API_BASE}/files/${encodeURIComponent(key)}`,
  deleteFile: (key: string) =>
    fetchApi<{ success: boolean }>(`/files/${encodeURIComponent(key)}`, {
      method: 'DELETE',
    }),
}

// Queue API
export const queueApi = {
  sendMessage: (message: unknown) =>
    fetchApi<{ success: boolean; message: string }>('/queue', {
      method: 'POST',
      body: JSON.stringify(message),
    }),
}

// Durable Objects API
export const doApi = {
  getCounter: (name: string) =>
    fetchApi<{ value: number }>(`/counter/${encodeURIComponent(name)}`),
  increment: (name: string) =>
    fetchApi<{ value: number }>(`/counter/${encodeURIComponent(name)}/increment`, {
      method: 'POST',
    }),
  decrement: (name: string) =>
    fetchApi<{ value: number }>(`/counter/${encodeURIComponent(name)}/decrement`, {
      method: 'POST',
    }),
  reset: (name: string) =>
    fetchApi<{ value: number }>(`/counter/${encodeURIComponent(name)}/reset`, {
      method: 'POST',
    }),
}

const API_BASE = '/api'

async function fetchApi<T>(endpoint: string, options?: RequestInit): Promise<T> {
  const response = await fetch(`${API_BASE}${endpoint}`, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...options?.headers,
    },
  })

  if (!response.ok) {
    const error = await response.json().catch(() => ({ error: 'Unknown error' }))
    throw new Error(error.error || `HTTP ${response.status}`)
  }

  return response.json()
}

// Bindings
export const bindingsApi = {
  getAll: () => fetchApi<BindingsResponse>('/bindings'),
}

// D1
export const d1Api = {
  list: () => fetchApi<{ databases: D1Database[] }>('/d1'),
  getSchema: (binding: string) => fetchApi<{ tables: D1Table[] }>(`/d1/${binding}/schema`),
  getTableInfo: (binding: string, table: string) =>
    fetchApi<{ table: string; columns: D1Column[]; rowCount: number }>(`/d1/${binding}/tables/${table}`),
  getRows: (binding: string, table: string, limit = 100, offset = 0) =>
    fetchApi<{ rows: Record<string, unknown>[]; meta: unknown }>(
      `/d1/${binding}/tables/${table}/rows?limit=${limit}&offset=${offset}`
    ),
  query: (binding: string, sql: string, params: unknown[] = []) =>
    fetchApi<{ success: boolean; results?: unknown[]; meta?: unknown }>(`/d1/${binding}/query`, {
      method: 'POST',
      body: JSON.stringify({ sql, params }),
    }),
  insertRow: (binding: string, table: string, data: Record<string, unknown>) =>
    fetchApi<{ success: boolean }>(`/d1/${binding}/tables/${table}/rows`, {
      method: 'POST',
      body: JSON.stringify(data),
    }),
  updateRow: (binding: string, table: string, id: string, data: Record<string, unknown>) =>
    fetchApi<{ success: boolean }>(`/d1/${binding}/tables/${table}/rows/${id}`, {
      method: 'PUT',
      body: JSON.stringify(data),
    }),
  deleteRow: (binding: string, table: string, id: string) =>
    fetchApi<{ success: boolean }>(`/d1/${binding}/tables/${table}/rows/${id}`, {
      method: 'DELETE',
    }),
}

// KV
export const kvApi = {
  list: () => fetchApi<{ namespaces: KVNamespace[] }>('/kv'),
  getKeys: (binding: string, prefix?: string, cursor?: string, limit = 100) => {
    const params = new URLSearchParams({ limit: String(limit) })
    if (prefix) params.set('prefix', prefix)
    if (cursor) params.set('cursor', cursor)
    return fetchApi<{ keys: KVKey[]; cursor?: string; list_complete: boolean }>(
      `/kv/${binding}/keys?${params}`
    )
  },
  getValue: (binding: string, key: string, type = 'text') =>
    fetchApi<{ key: string; value: unknown; metadata?: unknown }>(
      `/kv/${binding}/keys/${encodeURIComponent(key)}?type=${type}`
    ),
  setValue: (binding: string, key: string, value: string, metadata?: unknown, ttl?: number) =>
    fetchApi<{ success: boolean }>(`/kv/${binding}/keys/${encodeURIComponent(key)}`, {
      method: 'PUT',
      body: JSON.stringify({ value, metadata, expirationTtl: ttl }),
    }),
  deleteKey: (binding: string, key: string) =>
    fetchApi<{ success: boolean }>(`/kv/${binding}/keys/${encodeURIComponent(key)}`, {
      method: 'DELETE',
    }),
}

// R2
export const r2Api = {
  list: () => fetchApi<{ buckets: R2Bucket[] }>('/r2'),
  getObjects: (binding: string, prefix?: string, cursor?: string, limit = 100) => {
    const params = new URLSearchParams({ limit: String(limit) })
    if (prefix) params.set('prefix', prefix)
    if (cursor) params.set('cursor', cursor)
    return fetchApi<{ objects: R2Object[]; truncated: boolean; cursor?: string }>(
      `/r2/${binding}/objects?${params}`
    )
  },
  getObjectMeta: (binding: string, key: string) =>
    fetchApi<R2Object>(`/r2/${binding}/objects/${encodeURIComponent(key)}/meta`),
  deleteObject: (binding: string, key: string) =>
    fetchApi<{ success: boolean }>(`/r2/${binding}/objects/${encodeURIComponent(key)}`, {
      method: 'DELETE',
    }),
}

// Queues
export const queuesApi = {
  list: () => fetchApi<{ producers: QueueProducer[]; consumers: QueueConsumer[] }>('/queues'),
  send: (binding: string, message: unknown) =>
    fetchApi<{ success: boolean }>(`/queues/${binding}/send`, {
      method: 'POST',
      body: JSON.stringify({ message }),
    }),
}

// Durable Objects
export const doApi = {
  list: () => fetchApi<{ durableObjects: DurableObject[] }>('/do'),
  getInstances: () =>
    fetchApi<{ instances: DOInstance[] }>('/do/instances'),
  getId: (binding: string, options: { name?: string; id?: string }) =>
    fetchApi<{ id: string }>(`/do/${binding}/id`, {
      method: 'POST',
      body: JSON.stringify(options),
    }),
  fetch: async (binding: string, id: string, path: string, options?: RequestInit) => {
    const response = await fetch(`/api/do/${binding}/${id}/fetch${path}`, {
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...options?.headers,
      },
    })
    return response
  },
}

export interface DOInstance extends Record<string, unknown> {
  binding: string
  class_name: string
  id: string
}

// Types
export interface BindingsResponse {
  name: string
  bindings: {
    d1: { type: string; binding: string; database_name: string }[]
    kv: { type: string; binding: string }[]
    r2: { type: string; binding: string; bucket_name: string }[]
    durableObjects: { type: string; name: string; binding: string; class_name: string; script_name?: string }[]
    queues: {
      producers: { type: string; binding: string; queue: string }[]
      consumers: { type: string; queue: string }[]
    }
    vars: { type: string; key: string; value: string }[]
  }
}

export interface D1Database {
  binding: string
  database_name: string
  database_id: string
}

export interface D1Table {
  name: string
  sql: string
}

export interface D1Column {
  cid: number
  name: string
  type: string
  notnull: number
  dflt_value: unknown
  pk: number
}

export interface KVNamespace {
  binding: string
  id: string
}

export interface KVKey {
  name: string
  expiration?: number
  metadata?: unknown
}

export interface R2Bucket {
  binding: string
  bucket_name: string
}

export interface R2Object {
  key: string
  size: number
  etag: string
  httpEtag: string
  uploaded: string
  checksums?: unknown
  customMetadata?: Record<string, string>
  httpMetadata?: {
    contentType?: string
    contentDisposition?: string
  }
}

export interface QueueProducer {
  binding: string
  queue: string
}

export interface QueueConsumer {
  queue: string
  max_batch_size: number
  max_batch_timeout: number
  max_retries: number
  dead_letter_queue?: string
}

export interface DurableObject {
  name: string
  class_name: string
  script_name?: string
}

// Logs
export interface LogEntry {
  id: string
  timestamp: string
  level: 'log' | 'info' | 'warn' | 'error' | 'debug'
  source: 'worker' | 'queue' | 'do' | 'system'
  message: string
  data?: unknown
}

export const logsApi = {
  getRecent: (limit = 100) => fetchApi<{ logs: LogEntry[] }>(`/logs?limit=${limit}`),
  clear: () => fetchApi<{ success: boolean }>('/logs', { method: 'DELETE' }),
  // SSE stream is handled separately via EventSource
}

import * as React from "react"
import { HugeiconsIcon } from "@hugeicons/react"
import { Search01Icon, Cancel01Icon } from "@hugeicons/core-free-icons"
import { cn } from "@/lib/utils"

interface SearchInputProps extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "onChange"> {
  value: string
  onChange: (value: string) => void
  onClear?: () => void
  showShortcut?: boolean
  className?: string
}

export function SearchInput({
  value,
  onChange,
  onClear,
  showShortcut = false,
  placeholder = "Search...",
  className,
  ...props
}: SearchInputProps) {
  const inputRef = React.useRef<HTMLInputElement>(null)

  const handleClear = () => {
    onChange("")
    onClear?.()
    inputRef.current?.focus()
  }

  React.useEffect(() => {
    if (!showShortcut) return

    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.metaKey || e.ctrlKey) && e.key === "k") {
        e.preventDefault()
        inputRef.current?.focus()
      }
    }

    document.addEventListener("keydown", handleKeyDown)
    return () => document.removeEventListener("keydown", handleKeyDown)
  }, [showShortcut])

  return (
    <div className={cn("relative", className)}>
      <HugeiconsIcon
        icon={Search01Icon}
        className="absolute left-3 top-1/2 -translate-y-1/2 size-4 text-muted-foreground pointer-events-none"
        strokeWidth={2}
      />
      <input
        ref={inputRef}
        type="text"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className={cn(
          "w-full h-9 pl-9 pr-9 text-sm bg-background border border-input rounded-md",
          "placeholder:text-muted-foreground",
          "focus:outline-none focus:ring-2 focus:ring-ring focus:border-transparent",
          "transition-colors"
        )}
        {...props}
      />
      {value ? (
        <button
          type="button"
          onClick={handleClear}
          className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
        >
          <HugeiconsIcon icon={Cancel01Icon} className="size-4" strokeWidth={2} />
        </button>
      ) : showShortcut ? (
        <kbd className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] text-muted-foreground font-mono bg-muted px-1.5 py-0.5 rounded border border-border">
          {navigator.platform.includes("Mac") ? "⌘K" : "Ctrl+K"}
        </kbd>
      ) : null}
    </div>
  )
}

